class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def introduce(self):
        print(self.name + "는 " + str(self.age) + "살입니다")

p = Person("파이코치", 5)
p.introduce()

class Counter:
    def __init__(self):
        self.count = 0

    def increase(self):
        self.count += 1

c = Counter()
c.increase()
c.increase()
c.increase()
print(c.count)

class Circle:
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return self.radius * self.radius * 3.14

c = Circle(5)
print(c.area())

class Account:
    def __init__(self, balance):
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        self.balance -= amount

account = Account(1000)
account.deposit(500)
account.withdraw(300)
print(account.balance)
